import {meltPortrait} from './melt.js';
import {COLORS,ART,CELLS,clone,newGame,place,makeTray,total,isComplete,isFull} from './engine.js';
const $=s=>document.querySelector(s),board=$('#board'),tray=$('#tray'),ctx=board.getContext('2d'),tc=tray.getContext('2d');
let saved={completed:[],sound:false};try{saved={...saved,...JSON.parse(localStorage.getItem('portrait-atelier')||'{}')};}catch{}
let state=newGame(),selected=-1,hover=-1,keyboardCell=4,busy=false,brush=false,history=[],viewBoard=null,mergeAnimation=null,clearAnimation=null,drag=null,toastTimer,audioCtx,intro=null;
const R=31,positions=CELLS.map(({q,r})=>({x:260+Math.sqrt(3)*R*(q+r/2),y:171+1.5*R*r}));
const trayPositions=[{x:150,y:52},{x:260,y:52},{x:370,y:52}];
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function save(){try{localStorage.setItem('portrait-atelier',JSON.stringify(saved));}catch{}}
function artPosition(i){return `${(i%4)*100/3}% ${Math.floor(i/4)*50}%`;}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200);}
function sound(kind=0){if(!saved.sound)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const t=audioCtx.currentTime;const notes=kind===2?[523.25,659.25,783.99,1046.5]:kind===1?[440,554.37,659.25]:[330,440];notes.forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t+i*.055);g.gain.linearRampToValueAtTime(.045,t+i*.055+.01);g.gain.exponentialRampToValueAtTime(.001,t+i*.055+.23);o.connect(g);g.connect(audioCtx.destination);o.start(t+i*.055);o.stop(t+i*.055+.25);});}catch{}}
function hexPath(c,x,y,r){c.beginPath();for(let i=0;i<6;i++){const a=(i*60-90)*Math.PI/180;const px=x+Math.cos(a)*r,py=y+Math.sin(a)*r;if(i===0)c.moveTo(px,py);else c.lineTo(px,py);}c.closePath();}
function hex(c,x,y,r,fill,stroke){hexPath(c,x,y,r);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke();}}
function stack(c,arr,x,y,r=R,alpha=1){if(!arr.length)return;c.save();c.globalAlpha=alpha;c.shadowColor='#57442530';c.shadowBlur=9;c.shadowOffsetY=6;hex(c,x,y+4,r,'#a88b64');c.shadowBlur=0;c.shadowOffsetY=0;arr.forEach((color,i)=>{const offset=Math.min(i,13)*3.3,col=COLORS[color];hex(c,x,y-offset,r,col.dark,'#705d2a20');hex(c,x,y-offset-3,r,col.hex,'#ffffff55');if(i===arr.length-1){const g=c.createLinearGradient(x-r,y-offset-r,x+r,y-offset+r);g.addColorStop(0,'#ffffff35');g.addColorStop(.5,'#ffffff0a');g.addColorStop(1,'#00000007');hex(c,x,y-offset-3,r-1,g);hexPath(c,x,y-offset-3,r-4);c.strokeStyle='#ffffff22';c.lineWidth=1;c.stroke();}});if(arr.length>1){c.font='500 10px -apple-system,sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillStyle='#ffffffc9';c.fillText(arr.length,x,y-Math.min(arr.length-1,13)*3.3-1);}c.restore();}
function draw(){ctx.setTransform(2,0,0,2,0,0);ctx.clearRect(0,0,520,335);const b=viewBoard||state.board;const stamp=performance.now();const colorIn=intro?Math.max(0,Math.min(1,(intro.progress-.28)/.49)):1;ctx.filter=`grayscale(${1-colorIn})`;ctx.globalAlpha=1;positions.forEach((p,i)=>{ctx.save();ctx.shadowColor='#70583626';ctx.shadowBlur=4;ctx.shadowOffsetY=4;hex(ctx,p.x,p.y+6,R-1,'#bc9d77');ctx.shadowBlur=0;ctx.shadowOffsetY=0;const target=!b[i].length&&((selected>=0&&hover===i)||(document.activeElement===board&&keyboardCell===i));hex(ctx,p.x,p.y,R-1,target?'#a8b595':brush&&b[i].length?'#d7a691':'#d1b690',target?'#f5f4df':'#b89b75');hexPath(ctx,p.x,p.y,R-5);ctx.strokeStyle='#f8e9ce25';ctx.stroke();if(target){ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillStyle='#f4f7e6';ctx.fillText('+',p.x,p.y+6);}ctx.restore();});
 positions.forEach((p,i)=>{if(mergeAnimation?.sources.some(s=>s.index===i))return;let alpha=1;if(clearAnimation?.target===i)alpha=Math.max(0,1-(stamp-clearAnimation.start)/300);if(intro){const arrival=.32+(p.y-78)/186*.18+Math.abs(p.x-260)/110*.06;const landing=Math.max(0,Math.min(1,(intro.progress-arrival)/.30));const bounce=landing<1?-Math.sin(landing*Math.PI)*9:0;ctx.save();ctx.filter=`grayscale(${1-landing})`;stack(ctx,b[i],p.x,p.y+bounce,R-2,alpha*(.3+.7*landing));ctx.restore();}else stack(ctx,b[i],p.x,p.y,R-2,alpha);});
 if(mergeAnimation){const t=Math.min(1,(stamp-mergeAnimation.start)/330),e=1-(1-t)**3;const target=positions[mergeAnimation.target];for(const s of mergeAnimation.sources){const p=positions[s.index],x=p.x+(target.x-p.x)*e,y=p.y+(target.y-p.y)*e-Math.sin(t*Math.PI)*20;stack(ctx,Array(s.count).fill(mergeAnimation.color),x,y,R-2);}}
 tc.setTransform(2,0,0,2,0,0);tc.clearRect(0,0,520,100);tc.filter=`grayscale(${1-colorIn})`;trayPositions.forEach((p,i)=>{const active=selected===i;tc.save();tc.beginPath();tc.ellipse(p.x,p.y+16,43,15,0,0,Math.PI*2);tc.fillStyle=active?'#8d9c6e22':'#b59b7612';tc.fill();if(active){tc.strokeStyle='#8e9e72';tc.lineWidth=1;tc.setLineDash([3,4]);tc.stroke();}tc.restore();stack(tc,state.tray[i],p.x,p.y-(active?5:0),25);if(!state.tray[i].length){tc.font='14px sans-serif';tc.fillStyle='#b8a38388';tc.textAlign='center';tc.fillText('·',p.x,p.y);} });requestAnimationFrame(draw);}
const regions=['M0 0H100V43L78 35 60 44 37 31 0 39Z','M100 0H200V46L176 40 150 50 122 35 100 43Z','M0 39L37 31 60 44 78 35 100 43V115L77 105 51 119 28 107 0 121Z','M100 43L122 35 150 50 176 40 200 46V114L170 122 145 109 120 120 100 115Z','M0 121L28 107 51 119 77 105 100 115V200H0Z','M100 115L120 120 145 109 170 122 200 114V200H100Z'];
function update(){const percent=Math.round(total(state)/72*100);$('#artistName').textContent=ART[state.art][0];$('#artistCaption').textContent=ART[state.art][1];$('#levelLabel').textContent=`作品 ${String(state.art+1).padStart(2,'0')}`;$('#score').textContent=state.score.toLocaleString();$('#progressNumber').innerHTML=`${percent}<span>%</span>`;$('#progressRing').style.strokeDashoffset=119.38*(1-percent/100);$('#goalTotal').innerHTML=`${total(state)} <em>/ 72</em>`;$('#sketch').style.backgroundPosition=artPosition(state.art);$('#painted').style.backgroundPosition=artPosition(state.art);$('#painted').style.clipPath='none';const mask=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200">${regions.map((d,i)=>`<path d="${d}" fill="white" opacity="${state.collected[i]/12}"/>`).join('')}</svg>`;$('#painted').style.maskImage=intro?'none':`url("data:image/svg+xml,${encodeURIComponent(mask)}")`;$('#colorGoals').innerHTML=COLORS.map((c,i)=>`<div class="color-goal ${state.collected[i]>=12?'completed':''}" title="${c.name}"><div class="goal-swatch" style="background:${c.hex}"></div><span>${state.collected[i]} / 12</span></div>`).join('');['undo','shuffle','brush'].forEach(k=>{$(`#${k}Count`).textContent=state.tools[k];$(`#${k}Btn`).disabled=busy||!state.tools[k]||(k==='undo'&&!history.length);});$('#switchArtBtn').disabled=busy;$('#brushBtn').style.color=brush?'#b67d5e':'';$('#boardMessage').textContent=brush?'点击一格，用画笔收走颜料':selected<0?'选一叠色块，放进空格':'相邻同色会自动聚拢 · 6 片消除';$('#collectionCount').textContent=`${saved.completed.length} / 12`;$('#soundBtn').style.opacity=saved.sound?1:.55;$('#soundBtn').setAttribute('aria-label',saved.sound?'关闭声音':'开启声音');$('#soundBtn').title=saved.sound?'关闭声音':'开启声音';renderCollection();}
function renderCollection(){const ids=[state.art,...[0,1,2,3].filter(i=>i!==state.art)].slice(0,4);$('#artList').innerHTML=ids.map(i=>`<button class="art-choice ${state.art===i?'selected':''}" data-art="${i}"><span class="art-thumb" style="background-position:${artPosition(i)}"></span><span class="art-info"><strong>${ART[i][0]}</strong><small>${ART[i][2]}</small><em>${saved.completed.includes(i)?'✓ 已收藏':state.art===i?'正在创作 · IN PROGRESS':'点击开始创作'}</em></span></button>`).join('');$('#galleryGrid').innerHTML=ART.map((a,i)=>`<button class="gallery-art" data-art="${i}"><span class="art-thumb" style="background-position:${artPosition(i)}"></span><strong>${a[0]}</strong><small>${saved.completed.includes(i)?'✓ 已收藏':String(i+1).padStart(2,'0')+' / 等待你的色彩'}</small></button>`).join('');}
async function begin(art,notice=true){
 if(busy)return;
 state=newGame(art);selected=-1;brush=false;history=[];viewBoard=null;
 intro={progress:0};busy=true;update();
 const studio=$('.studio');studio.setAttribute('aria-busy','true');
 $('#boardMessage').textContent='名画正在化作调色盘里的颜料…';
 try{
  await meltPortrait({studio,portrait:$('#portrait'),board,art,onProgress:p=>{intro.progress=p;}});
 }catch(error){console.error('Portrait opening animation:',error);}
 finally{intro=null;busy=false;studio.removeAttribute('aria-busy');update();}
 if(notice)toast(`开始创作 · ${ART[art][0]}`);
}
function localPoint(canvas,e){const rect=canvas.getBoundingClientRect();return {x:(e.clientX-rect.left)*520/rect.width,y:(e.clientY-rect.top)*canvas.height/2/rect.height};}
function hitCell(p){let best=-1,d=R;positions.forEach((a,i)=>{const distance=Math.hypot(a.x-p.x,a.y-p.y);if(distance<d){d=distance;best=i;}});return best;}
function choose(i){if(isComplete(state)){toast("这幅作品已完成，去作品集开启下一幅吧");return;}if(busy||!state.tray[i]?.length)return;selected=i;brush=false;sound();update();}
function historyPush(){history.push(clone(state));if(history.length>20)history.shift();}
function flyPaint(event){const rect=board.getBoundingClientRect(),p=positions[event.target],dest=$('#portrait').getBoundingClientRect();const x=rect.left+p.x/520*rect.width,y=rect.top+p.y/335*rect.height;for(let i=0;i<11;i++){const el=document.createElement('i');el.className='paint-particle';el.style.background=COLORS[event.color].hex;el.style.color=COLORS[event.color].hex;el.style.left=x+'px';el.style.top=y+'px';$('#effects').append(el);el.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${(i-5)*11}px,-65px) scale(.8)`,opacity:1,offset:.35},{transform:`translate(${dest.left+dest.width/2-x+(i-5)*5}px,${dest.top+dest.height*.5-y}px) scale(.3)`,opacity:0}],{duration:750,delay:i*19,easing:'cubic-bezier(.25,.6,.4,1)'}).onfinish=()=>el.remove();}const label=document.createElement('span');label.className='floating-score';label.textContent=`+${event.count*10}`;label.style.left=x+'px';label.style.top=(y-30)+'px';$('#effects').append(label);label.animate([{transform:'translate(-50%,0)',opacity:1},{transform:'translate(-50%,-65px)',opacity:0}],{duration:1000}).onfinish=()=>label.remove();}
async function animateEvents(events,oldCollected){let chain=0;for(const e of events){viewBoard=e.before;if(e.type==='merge'){mergeAnimation={...e,start:performance.now()};sound();await delay(345);mergeAnimation=null;}else{clearAnimation={...e,start:performance.now()};flyPaint(e);sound(1);await delay(310);clearAnimation=null;chain++;oldCollected[e.color]=Math.min(12,oldCollected[e.color]+e.count);const actual=state.collected;state.collected=oldCollected;update();state.collected=actual;}viewBoard=e.after;}viewBoard=null;if(chain>1)toast(`${chain} 连消！灵感正好 ✦`);}
async function put(index){if(busy||index<0)return;if(isComplete(state)){complete();return;}if(brush){await brushCell(index);return;}if(selected<0){toast('先从下方调色盘选一叠色块');return;}if(state.board[index].length){toast('这里已有颜料，试试空格');return;}busy=true;historyPush();const oldCollected=[...state.collected],events=place(state,index,selected);selected=-1;update();await animateEvents(events,oldCollected);if(isComplete(state)){await delay(600);busy=false;update();complete();}else{busy=false;update();if(isFull(state))showFull();}}
async function brushCell(index){if(!state.board[index].length){toast('选一个有颜料的格子');return;}historyPush();state.tools.brush--;const pile=state.board[index];const counts=COLORS.map((_,i)=>pile.filter(c=>c===i).length);state.board[index]=[];counts.forEach((n,i)=>{state.collected[i]=Math.min(12,state.collected[i]+n);});state.score+=pile.length*10;brush=false;flyPaint({target:index,color:pile.at(-1),count:pile.length});sound(1);update();if(isComplete(state))complete();}
function complete(){if(!saved.completed.includes(state.art)){saved.completed.push(state.art);save();}sound(2);update();$('#resultContent').innerHTML=`<span class="eyebrow">A MASTERPIECE, MADE BY YOU</span><div class="result-art" style="background-position:${artPosition(state.art)}"></div><h2>经典，因你而鲜活。</h2><p>《${ART[state.art][0]}》已收入作品集<br>${state.moves} 次落子 · ${state.score.toLocaleString()} 灵感积分</p><div class="result-actions"><button id="resultGallery">我的作品集</button><button class="primary-btn" id="nextArt">下一幅创作 ↗</button></div>`;$('#resultDialog').showModal();$('#nextArt').onclick=()=>{$('#resultDialog').close();begin((state.art+1)%ART.length);};$('#resultGallery').onclick=()=>{$('#resultDialog').close();$('#galleryDialog').showModal();};}
function showFull(){$('#resultContent').innerHTML=`<span class="eyebrow">TAKE A LITTLE BREATH</span><h2>画板需要一点空间。</h2><p>创作偶尔也会遇到瓶颈。<br>${state.tools.brush?'试试画笔，收走一格颜料。':state.tools.undo&&history.length?'撤销上一步，换个放置位置。':'重新开始，再找找新的灵感。'}</p><div class="result-actions"><button id="retryArt">重新创作</button>${state.tools.brush||state.tools.undo&&history.length?'<button class="primary-btn" id="keepArt">继续创作 ↗</button>':''}</div>`;$('#resultDialog').showModal();$('#retryArt').onclick=()=>{$('#resultDialog').close();begin(state.art);};$('#keepArt')?.addEventListener('click',()=>{$('#resultDialog').close();if(state.tools.brush){brush=true;selected=-1;update();toast('点击棋盘上任意一叠颜料');}else undo();});}
function undo(){if(busy||!history.length||!state.tools.undo)return;const tools={...state.tools,undo:state.tools.undo-1};state=history.pop();state.tools=tools;selected=-1;brush=false;update();sound();toast('回到上一步，再试一个位置');}
$('#undoBtn').onclick=undo;$('#shuffleBtn').onclick=()=>{if(busy||!state.tools.shuffle)return;historyPush();state.tools.shuffle--;state.tray=makeTray(state.board,state.collected);selected=-1;brush=false;update();sound();toast('新的色彩，新的灵感');};$('#brushBtn').onclick=()=>{if(busy||!state.tools.brush)return;brush=!brush;selected=-1;update();};$('#restartBtn').onclick=()=>begin(state.art);$('#soundBtn').onclick=()=>{saved.sound=!saved.sound;save();sound();update();};$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('#galleryTab').onclick=$('#allArtBtn').onclick=$('#switchArtBtn').onclick=()=>{$('#galleryDialog').showModal();};$('#studioTab').onclick=()=>document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.addEventListener('click',e=>{const a=e.target.closest('[data-art]');if(a){if(busy)return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());begin(Number(a.dataset.art));}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
tray.addEventListener('pointerdown',e=>{const p=localPoint(tray,e),i=trayPositions.findIndex(a=>Math.abs(a.x-p.x)<44&&Math.abs(a.y-p.y)<47);if(i<0||busy||!state.tray[i].length)return;choose(i);drag={i,x:e.clientX,y:e.clientY,moved:false,el:null};tray.setPointerCapture(e.pointerId);});tray.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7&&!drag.moved){drag.moved=true;drag.el=document.createElement('div');drag.el.className='drag-token';drag.el.style.background=COLORS[state.tray[drag.i].at(-1)].hex;drag.el.textContent=state.tray[drag.i].length;document.body.append(drag.el);}if(drag.el){drag.el.style.left=(e.clientX-30)+'px';drag.el.style.top=(e.clientY-55)+'px';hover=hitCell(localPoint(board,e));}});tray.addEventListener('pointerup',e=>{if(!drag)return;const moved=drag.moved;drag.el?.remove();drag=null;hover=-1;if(moved){const rect=board.getBoundingClientRect();if(e.clientX>=rect.left&&e.clientX<=rect.right&&e.clientY>=rect.top&&e.clientY<=rect.bottom)put(hitCell(localPoint(board,e)));}});tray.addEventListener('pointercancel',()=>{drag?.el?.remove();drag=null;hover=-1;});board.addEventListener('pointermove',e=>hover=hitCell(localPoint(board,e)));board.addEventListener('pointerleave',()=>hover=-1);board.addEventListener('click',e=>put(hitCell(localPoint(board,e))));document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(['1','2','3'].includes(e.key)){choose(Number(e.key)-1);e.preventDefault();}if(e.key==='Escape'){selected=-1;brush=false;update();}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const p=positions[keyboardCell],direction={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];const options=positions.map((n,i)=>({i,dx:n.x-p.x,dy:n.y-p.y})).filter(n=>n.dx*direction[0]+n.dy*direction[1]>10).sort((a,b)=>Math.hypot(a.dx,a.dy)-(a.dx*direction[0]+a.dy*direction[1])*.5-(Math.hypot(b.dx,b.dy)-(b.dx*direction[0]+b.dy*direction[1])*.5));if(options.length)keyboardCell=options[0].i;board.focus();}if(e.key==='Enter'&&document.activeElement===board){e.preventDefault();put(keyboardCell);}});
begin(0,false);draw();
